<?php /** @var array<string,mixed>|null $s */ /** @var list<array<string,mixed>> $clients */ /** @var list<array<string,mixed>> $projects */ $v = static fn (string $k, string $d = ''): string => old($k, $d); ?>
<div class="page-head"><div><p class="eyebrow">Services</p><h1>Add a domain or hosting service</h1></div><a class="btn btn-ghost" href="/renewals">&larr; Services</a></div>
<div class="panel"><p class="muted">Record the service and its dates. <strong>Never type a provider password, key or authorisation code here.</strong> Keep credentials in the provider's own account or a password manager.</p>
    <form method="post" action="/renewals" class="form-grid"><?= csrf_field() ?>
        <div class="field"><label for="c">Client</label><select id="c" name="client" required><option value="">Choose…</option><?php foreach ($clients as $c) : ?><option value="<?= e($c['public_id']) ?>"<?= $v('client') === $c['public_id'] ? ' selected' : '' ?>><?= e($c['company_name'] ?: $c['contact_name']) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="p">Project (optional)</label><select id="p" name="project"><option value="">None</option><?php foreach ($projects as $p) : ?><option value="<?= e($p['public_id']) ?>"<?= $v('project') === $p['public_id'] ? ' selected' : '' ?>><?= e($p['code']) ?> · <?= e($p['title']) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="t">Type</label><select id="t" name="service_type" required><?php foreach (config('renewals.types') as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('service_type') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="i">Domain name or plan name</label><input id="i" name="identifier" required maxlength="190" value="<?= e($v('identifier')) ?>" placeholder="example.com"></div>
        <div class="field"><label for="pr">Provider or registrar</label><input id="pr" name="provider" required maxlength="120" value="<?= e($v('provider')) ?>"></div>
        <div class="field"><label for="a">Activation date</label><input id="a" name="activated_on" type="date" required value="<?= e($v('activated_on')) ?>"></div>
        <div class="field"><label for="x">Expiry date</label><input id="x" name="expires_on" type="date" required value="<?= e($v('expires_on')) ?>"></div>
        <div class="field"><label for="m">Renewal period</label><select id="m" name="period_months"><?php foreach (config('renewals.periods') as $m) : ?><option value="<?= (int) $m ?>"<?= $v('period_months', '12') === (string) $m ? ' selected' : '' ?>><?= (int) $m ?> month<?= $m === 1 ? '' : 's' ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="n">Internal notes (staff only)</label><textarea id="n" name="internal_notes" rows="3" maxlength="3000"><?= e($v('internal_notes')) ?></textarea></div>
        <div class="field"><label for="cn">Notes the client can see</label><textarea id="cn" name="client_notes" rows="2" maxlength="1000"><?= e($v('client_notes')) ?></textarea></div>
        <div class="field"><label class="check"><input type="checkbox" name="client_reminders" value="1"<?= $v('client_reminders', '1') === '1' ? ' checked' : '' ?>> Remind the client in the portal as the expiry approaches</label></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Add service</button></div></form></div>
